using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyLootTests
    {
        static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        public static CampusSolid[] Flat=>new[]{new CampusSolid{name="Ground",center=new Vector3(0,-.5f,0),size=new Vector3(80,1,64)}};
        static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        public static PersonaInstance Loose(Match m,Vector3 position,string who="p2")
        {var item=m.Items.First(x=>x.ownerId==who&&x.state==ItemState.Inventory);item.state=ItemState.Ground;item.position=position;item.velocity=Vector3.zero;return item;}
        public static EffectState Line(Match m)
        {var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.5f);var a=m.Players["p0"];a.position=new Vector3(3,1,0);a.motorHeight=1;if(m.BodyWorld!=null)m.BodyWorld.Reset(a);PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.32f);Check(e.stage=="line_armed","second F did not arm line");return e;}
        public static void Run()
        {
            var old=Cache.GetValue(null);int passed=0;var failures=new System.Collections.Generic.List<string>();
            void Test(string name,Action run){Cache.SetValue(null,Flat);try{run();passed++;Debug.Log("PARTY_LOOT_PASS "+name);}catch(Exception ex){failures.Add(name+": "+ex.Message);Debug.LogError("PARTY_LOOT_FAIL "+name+": "+ex);}}
            try
            {
                Test("own beacon exposes one nearest own Ground only to owner",()=>{using(var m=PartyFieldTests.Make("own-item-beacon")){var own=Loose(m,new Vector3(0,.35f,3),"p0");Loose(m,new Vector3(0,.35f,2));var e=PartyFieldTests.Deploy(m);Check(e.hit.SequenceEqual(new[]{own.id})&&m.View("p0").effects.Any(x=>x.id==e.id)&&!m.View("p1").effects.Any(x=>x.id==e.id),"beacon exposed enemy or private direction");own.state=ItemState.Inventory;PartyFieldTests.Tick(m,.02f);Check(e.hit.Count==0&&e.path.Length==0,"beacon retained recovered life");}});
                Test("radar counts only visible Ground within seven metres",()=>{using(var m=PartyFieldTests.Make("loose-radar")){Loose(m,new Vector3(0,.35f,3));Loose(m,new Vector3(0,.35f,-3),"p1");Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(0,1,-1.5f),size=new Vector3(4,2,.2f)}}).ToArray());var e=PartyFieldTests.Deploy(m);Check(e.hit.Count==1&&e.path[0].z>0&&!m.View("p2").effects.Any(x=>x.id==e.id),"radar saw through wall/private disclosure");}});
                Test("empty tongs and own-only rescue do not spend cooldown",()=>{foreach(var id in new[]{"tongs-place","rescue-tow"})using(var m=PartyFieldTests.Make(id)){if(id=="rescue-tow")Loose(m,new Vector3(0,.35f,2));PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.32f);Check(!m.Effects.Any(x=>x.kind=="PartyMechanic")&&m.View("p0").players.First(x=>x.id=="p0").mechanicCooldown<1,"empty cast spent cooldown or rescued enemy");}});
                Test("tongs places exact foreign life beside caster then E swallows normally",()=>{using(var m=PartyFieldTests.Make("tongs-place")){var item=Loose(m,new Vector3(0,.35f,1.4f));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.34f);Check(item.ownerId=="p2"&&item.state==ItemState.Ground&&item.position.x>.6f&&Mathf.Abs(item.position.z)<.4f,"tongs stole/duplicated life or did not put beside caster "+item.position);PartyFieldTests.Input(m,"p0","interact");PartyFieldTests.Tick(m,2.6f);Check(item.state==ItemState.Consumed&&m.Remaining("p2")==3&&m.Eaten.Count==1,"placed life skipped normal E consumption");}});
                Test("tongs blocks E while moving and Q releases with unchanged owner",()=>{using(var m=PartyFieldTests.Make("tongs-place")){var item=Loose(m,new Vector3(0,.35f,1.5f));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Input(m,"p0","interact");Check(item.state==ItemState.Ground,"clamp did not block E");PartyFieldTests.Input(m,"p0","cancel");Check(!m.Effects.Contains(e)&&item.state==ItemState.Ground&&item.ownerId=="p2","Q deleted reserved life");}});
                Test("rescue tow moves only exact own Ground slowly and stops before caster",()=>{using(var m=PartyFieldTests.Make("rescue-tow")){var item=Loose(m,new Vector3(0,.35f,4),"p0");var enemy=Loose(m,new Vector3(0,.35f,3));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,1.9f);Check(item.position.z<1&&item.position.z>.7f&&enemy.position.z==3&&item.state==ItemState.Ground&&m.Remaining("p0")==4,"tow did not preserve/manual-recover own life "+item.position);PartyFieldTests.Input(m,"p0","interact");PartyFieldTests.Tick(m,1.6f);Check(item.state==ItemState.Inventory&&m.Eaten.Count==0,"tow bypassed own E recovery");}});
                Test("tow is canceled by new wall and never teleports across it",()=>{using(var m=PartyFieldTests.Make("rescue-tow")){var item=Loose(m,new Vector3(0,.35f,4),"p0");var e=PartyFieldTests.Deploy(m);Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(0,1,2),size=new Vector3(4,2,.2f)}}).ToArray());float before=item.position.z;PartyFieldTests.Tick(m,.2f);Check(!m.Effects.Contains(e)&&Mathf.Abs(before-item.position.z)<.01f,"tow crossed wall");}});
                Test("float holds Ground above floor but E can still consume it",()=>{using(var m=PartyFieldTests.Make("float-lift")){var item=Loose(m,new Vector3(0,.35f,2));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.2f);Check(item.position.y>.9f&&item.state==ItemState.Ground&&item.ownerId=="p2","float changed life state");PartyFieldTests.Input(m,"p0","interact");PartyFieldTests.Tick(m,2.6f);Check(item.state==ItemState.Consumed&&!m.Effects.Contains(e)&&m.Eaten.Count==1,"float prevented original E consumption");}});
                Test("cradle carries at most two original lives and anyone can E take",()=>{using(var m=PartyFieldTests.Make("carry-cradle")){var one=Loose(m,new Vector3(-.15f,.35f,1.2f));var two=Loose(m,new Vector3(.15f,.35f,1.2f));var third=Loose(m,new Vector3(.4f,.35f,1.3f));var e=PartyFieldTests.Deploy(m);var prop=m.Props.First();Check(e.hit.Count==2&&e.hit.Contains(one.id)&&e.hit.Contains(two.id)&&!e.hit.Contains(third.id),"cradle cargo budget wrong");prop.holder="p0";m.Players["p0"].publicProp=prop.id;PartyFieldTests.Tick(m,.4f,"p0",1,0);Check(one.position.x>.2f&&one.state==ItemState.Ground&&m.Players["p0"].fieldStatus.Contains("搬盘"),"held cradle failed to transport/slows player");var b=m.Players["p1"];b.position=one.position+Vector3.back; b.position=new Vector3(b.position.x,1,b.position.z);PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Tick(m,2.6f);Check(one.state==ItemState.Consumed&&e.hit.Count<=1&&m.Remaining("p2")==3,"cradle protected life from E");}});
                Test("cradle removed source or device leaves its cargo as exact Ground",()=>{foreach(bool consumed in new[]{false,true})using(var m=PartyFieldTests.Make("carry-cradle")){var item=Loose(m,new Vector3(0,.35f,1.2f));var e=PartyFieldTests.Deploy(m);if(consumed)m.Item(e.sourceInstance).state=ItemState.Consumed;else m.Props.Clear();PartyFieldTests.Tick(m,.04f);Check(!m.Effects.Contains(e)&&item.state==ItemState.Ground&&item.ownerId=="p2"&&m.Remaining("p2")==4,"cradle teardown erased cargo");}});
                Test("swap warns then exchanges two public boxes without moving people",()=>{using(var m=PartyFieldTests.Make("mischief-swap-props")){var a=new PublicProp{id="box-a",visual="box",position=new Vector3(2,.6f,2)};var b=new PublicProp{id="box-b",visual="trash",position=new Vector3(-2,.6f,2)};m.Props.Add(a);m.Props.Add(b);var e=PartyFieldTests.Deploy(m);Check(a.position.x==2&&e.stage=="swap_warning","swap skipped warning");PartyFieldTests.Tick(m,.62f);Check(a.position.x==-2&&b.position.x==2&&m.Players["p0"].position.x==0&&m.CombatEvents.Count(x=>x.kind=="party_prop_swap")==1,"swap did not exchange public objects exactly once");}});
                Test("swap cancels when public box picked up or a character occupies destination",()=>{foreach(bool held in new[]{false,true})using(var m=PartyFieldTests.Make("mischief-swap-props")){var a=new PublicProp{id="box-a",visual="box",position=new Vector3(2,.6f,2)};var b=new PublicProp{id="box-b",visual="trash",position=new Vector3(-2,.6f,2)};m.Props.Add(a);m.Props.Add(b);var e=PartyFieldTests.Deploy(m);if(held){a.holder="p1";m.Players["p1"].publicProp=a.id;}else m.Players["p1"].position=new Vector3(2,1,2);PartyFieldTests.Tick(m,.7f);Check(!m.Effects.Contains(e)&&b.position.x==-2&&!m.CombatEvents.Any(x=>x.kind=="party_prop_swap"),"unsafe swap materialized box in player");}});
                Test("hot potato cannot transfer without active offer and recipient G",()=>{using(var m=PartyFieldTests.Make("public-hot-potato")){var e=PartyFieldTests.Deploy(m);var prop=m.Props.First();prop.holder="p0";m.Players["p0"].publicProp=prop.id;m.Players["p1"].position=new Vector3(0,1,2);m.Players["p1"].yaw=180;PartyFieldTests.Tick(m,.6f);Check(prop.holder=="p0"&&m.Players["p1"].publicProp=="","hot potato forced transfer");PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.18f);Check(e.stage=="offered"&&prop.holder=="p0","offer auto handoff");PartyFieldTests.Input(m,"p1","grab");PartyFieldTests.Tick(m,.22f);Check(prop.holder=="p1"&&m.Players["p0"].publicProp==""&&m.Players["p1"].publicProp==prop.id&&m.CombatEvents.Count(x=>x.kind=="party_hot_handoff")==1,"voluntary G transfer failed");}});
                Test("second F throws offered potato and expiry bursts exactly once then cleans up",()=>{using(var m=PartyFieldTests.Make("public-hot-potato")){var e=PartyFieldTests.Deploy(m);var prop=m.Props.First();prop.holder="p0";m.Players["p0"].publicProp=prop.id;PartyFieldTests.Tick(m,.6f);PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.7f);PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.18f);Check(prop.holder==""&&prop.thrower=="p0"&&prop.velocity.magnitude>5,"second F did not throw");PartyFieldTests.Tick(m,4);Check(!m.Effects.Contains(e)&&!m.Props.Contains(prop)&&m.CombatEvents.Count(x=>x.kind=="party_burst")==1&&m.Remaining("p0")==4,"potato exploded repeatedly/leaked or became extra life");}});
                Test("gentle rescue preserves grounded recovery deadline health and original lives",()=>{using(var m=PartyFieldTests.Make("gentle-push-clear")){var b=m.Players["p1"];b.position=new Vector3(0,.6f,1.5f);b.bodyMode=BodyMode.Grounded;b.bodyStateAt=m.Time;b.staggerUntil=m.Time+3;var before=b.position;var e=PartyFieldTests.Deploy(m);Check(b.position.z>before.z&&b.stability==100&&b.bodyStateAt==10&&m.Remaining("p1")==4&&m.CombatEvents.Count(x=>x.kind=="party_gentle_rescue")==1,"rescue damaged/deferred recovery/deleted life");}});
                Test("trip two ends hit running crossing once but walkers remain safe",()=>{foreach(bool run in new[]{false,true})using(var m=PartyFieldTests.Make("trip-line")){var e=Line(m);var b=m.Players["p1"];b.position=new Vector3(1.5f,1,.6f);b.yaw=0;for(int i=0;i<20;i++){foreach(var p in m.Players.Values)m.Receive(p.profile.playerId,new Command{sequence=p.sequence+1,yaw=p.yaw,z=p==b?1:0,run=p==b&&run});m.Tick(.02f);}Check(run?m.Items.Count(x=>x.ownerId=="p1"&&x.state==ItemState.Ground)==1&&m.CombatEvents.Count(x=>x.kind=="party_trip")==1:b.stability==100&&!m.CombatEvents.Any(x=>x.kind=="party_trip"),"line running/walking rule wrong run="+run+" pos="+b.position+" health="+b.stability);}});
                Test("trip endpoints dismantle together without life damage",()=>{using(var m=PartyFieldTests.Make("trip-line")){var e=Line(m);var b=m.Players["p1"];b.position=e.position+Vector3.up*.85f+Vector3.back*.8f;b.yaw=0;m.Item(b.equipped).asset.templateId="Melee";for(int i=0;i<2;i++){PartyFieldTests.Input(m,"p1","use_item");PartyFieldTests.Tick(m,1.3f);}Check(!m.Effects.Any(x=>x.mechanicId=="trip-line")&&m.Remaining("p0")==4,"line partner survived dismantle or source damaged");}});
                Test("all loot presentation uses authoritative phases and bounded pointers",()=>{foreach(var d in PartyMechanicRegistry.All.Where(x=>x.family=="loot"))using(var m=PartyFieldTests.Make(d.id)){if(d.id=="tongs-place"||d.id=="float-lift")Loose(m,new Vector3(0,.35f,1.4f));if(d.id=="rescue-tow")Loose(m,new Vector3(0,.35f,3),"p0");if(d.id=="mischief-swap-props"){m.Props.Add(new PublicProp{id="a",visual="box",position=new Vector3(2,.6f,2)});m.Props.Add(new PublicProp{id="b",visual="box",position=new Vector3(-2,.6f,2)});}if(d.id=="gentle-push-clear"){var b=m.Players["p1"];b.position=new Vector3(0,.6f,1.5f);b.bodyMode=BodyMode.Grounded;b.bodyStateAt=m.Time;b.staggerUntil=m.Time+3;}var e=PartyFieldTests.Deploy(m);var go=PartyMechanicVisual.Create(e,null);try{go.GetComponent<PartyMechanicVisual>().Present(e,m.Time,null,m.View("p0"));Check(go.GetComponentsInChildren<LineRenderer>(true).Length==7,"unbounded visual pointer allocation");}finally{UnityEngine.Object.DestroyImmediate(go);}}});
                Test("private loot Q disconnect consume and finish cleanup leaves lives exact",()=>{foreach(var mode in new[]{"cancel","disconnect","consume","finish"})using(var m=PartyFieldTests.Make("own-item-beacon")){var item=Loose(m,new Vector3(0,.35f,3),"p0");var e=PartyFieldTests.Deploy(m);if(mode=="cancel")PartyFieldTests.Input(m,"p0","cancel");if(mode=="disconnect")m.Disconnect("p0");if(mode=="consume")m.Item(e.sourceInstance).state=ItemState.Consumed;if(mode=="finish")m.Finish("timeout");if(m.Active)PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&item.state==ItemState.Ground&&m.Remaining("p0")== (mode=="consume"?3:4),"private cleanup erased/duplicated lives "+mode);}});
            }
            finally{Cache.SetValue(null,old);}
            if(failures.Count>0)throw new Exception(string.Join("\n",failures));Debug.Log("PARTY_LOOT_PASSED "+passed+" authority scenarios / ten loot interactions / exact Persona ownership and consent preserved");
        }
    }
}
